parts.text:
[
  {
    "statement": "Setting catch limits or quotas for non-targeted commercial fish reduced unwanted catch in two of three cases in one review.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "One study found that catch limits for non-target commercial species reduced the amount of unwanted halibut.",
    "citations": [
      "2693"
    ]
  },
  {
    "statement": "One study found that trawl nets fitted with a larger mesh codend caught fewer combined species of non-commercial unwanted invertebrates and fish compared to a traditional codend.",
    "citations": [
      "2135"
    ]
  },
  {
    "statement": "One study found that trawl nets fitted with a larger mesh codend caught a lower combined biomass and abundance of non-commercial unwanted invertebrates and fish compared to a traditional codend.",
    "citations": [
      "2135"
    ]
  },
  {
    "statement": "A study on trawl nets found that a larger mesh codend caught less biomass and abundance of commercially targeted shrimps.",
    "citations": [
      "2135"
    ]
  },
  {
    "statement": "A study on trawl nets found that the biomass ratios of commercially targeted to discard species was similar for both a larger mesh codend and a traditional codend.",
    "citations": [
      "2135"
    ]
  },
  {
    "statement": "Another study found that using larger mesh sizes in the inner and/or outer panels of trammel nets did not reduce the abundance of unwanted catch of non-commercial invertebrates.",
    "citations": [
      "2141"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of setting unwanted catch quotas on subtidal benthic invertebrate populations.",
    "citations": [
      "2116"
    ]
  }
]
